with unpacked as (select id, created_at, items, size(attributes) as num_attributes, array_contains(map_keys(attributes), 'weight_kg') as has_weight_kg, exists(items, i -> i.price > 100) as has_premium_item, attributes['utm_source'] as utm_source, forall(items, i -> i.qty <= 5) as all_small_qty from carts) select case when num_attributes >= 74 then 'PREMIUM' else 'STANDARD' end as num_attributes_tier, count(distinct utm_source) as distinct_utm_sources, round(avg(num_attributes), 2) as avg_num_attributes from unpacked group by num_attributes_tier;
